 return `<div class="rs-v3">${adminV3Heading('NEGOCIO','Revendedores','Administra las solicitudes de planes y su aprobación.')}${adminV3Panel('Solicitudes · '+S.planRequests.length,'Aprueba solo cuando hayas verificado el pago.',`<div class="rs-v3-form-actions"><button type="button" class="btn btn-outline" id="refreshPlans">Actualizar solicitudes</button></div><div class="rs-v3-list">${rows||adminV3Blank('Todavía no hay solicitudes de plan.')}</div>`)}</div>`;
